import{_ as e,c as r,o as t,a0 as i}from"./chunks/framework.DKRgXLPU.js";const n=JSON.parse('{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice.","frontmatter":{"title":"Understanding the Inner Critic","description":"Learn to recognize and manage the negative self-talk that undermines your pétanque performance. Transform your inner critic into a supportive voice."},"headers":[],"relativePath":"da/blog/inner-critic.md","filePath":"da/blog/inner-critic.md"}');const a=e({name:"da/blog/inner-critic.md"},[["render",function(e,n,a,d,l,s){return t(),r("div",null,[...n[0]||(n[0]=[i('<h1 id="at-forsta-den-indre-kritiker" tabindex="-1">At forstå den indre kritiker <a class="header-anchor" href="#at-forsta-den-indre-kritiker" aria-label="Permalink to &quot;At forstå den indre kritiker&quot;">​</a></h1><p>Enhver petanquespiller kender den stemme. Den der hvisker &quot;du kommer til at misse&quot; lige når du er ved at kaste. Den der afspiller dit sidste mislykkede slag i en endeløs løkke. Dette er din indre kritiker - og det er vigtigt at lære at håndtere den for at kunne præstere på eliteniveau.</p><h2 id="hvad-er-den-indre-kritiker" tabindex="-1">Hvad er den indre kritiker? <a class="header-anchor" href="#hvad-er-den-indre-kritiker" aria-label="Permalink to &quot;Hvad er den indre kritiker?&quot;">​</a></h2><p>Den indre kritiker er den indre stemme, der dømmer, kritiserer og underminerer din selvtillid. I petanque dukker den ofte op i de værst tænkelige øjeblikke:</p><ul><li><strong>Før et afgørende skud</strong>: &quot;Alle ser med. Lad være med at ødelægge det her.&quot;</li><li><strong>Efter en misser</strong>: &quot;Du kvæles altid under pres.&quot;</li><li><strong>Under en taberrække</strong>: &quot;Du er ikke god nok til dette niveau.&quot;</li></ul><p>Denne stemme prøver ikke at såre dig – det er faktisk et misforstået forsøg på beskyttelse. Din hjerne prøver at forberede dig på fiasko, så det ikke gør så ondt. Men denne &quot;beskyttelse&quot; bliver til selvsabotage.</p><h2 id="at-genkende-dine-mønstre" tabindex="-1">At genkende dine mønstre <a class="header-anchor" href="#at-genkende-dine-mønstre" aria-label="Permalink to &quot;At genkende dine mønstre&quot;">​</a></h2><p>Det første skridt er bevidsthed. Begynd at lægge mærke til, hvornår din indre kritiker dukker op:</p><h3 id="almindelige-udløsere" tabindex="-1">Almindelige udløsere <a class="header-anchor" href="#almindelige-udløsere" aria-label="Permalink to &quot;Almindelige udløsere&quot;">​</a></h3><ul><li>Situationer med højt pres (kampbold, vigtige turneringer)</li><li>Efter at have begået en fejl</li><li>Når modstanderne spiller godt</li><li>Når holdkammerater virker frustrerede</li><li>Fysisk træthed eller ubehag</li></ul><h3 id="almindelige-beskeder" tabindex="-1">Almindelige beskeder <a class="header-anchor" href="#almindelige-beskeder" aria-label="Permalink to &quot;Almindelige beskeder&quot;">​</a></h3><ul><li>&quot;Du kan ikke klare presset&quot;</li><li>&quot;Du er ikke lige så god som dem&quot;</li><li>&quot;Alle dømmer dig&quot;</li><li>&quot;Du fejler altid, når det gælder&quot;</li></ul><h2 id="indvirkningen-pa-præstationen" tabindex="-1">Indvirkningen på præstationen <a class="header-anchor" href="#indvirkningen-pa-præstationen" aria-label="Permalink to &quot;Indvirkningen på præstationen&quot;">​</a></h2><p>Når den indre kritiker tager over, reagerer din krop:</p><ol><li><strong>Muskelspændingen stiger</strong> — Dit kast bliver stift</li><li><strong>Årdrættet bliver overfladisk</strong> — Mindre ilt, mindre fokus</li><li><strong>Synet snævres</strong> — Du mister bevidstheden om terrænet</li><li><strong>Beslutningstagningen lider</strong> — Du tvivler på dig selv</li></ol><p>Dette skaber en ond cirkel: den indre kritiker forårsager dårlig præstation, hvilket giver kritikeren mere ammunition.</p><h2 id="strategier-til-at-handtere-den-indre-kritiker" tabindex="-1">Strategier til at håndtere den indre kritiker <a class="header-anchor" href="#strategier-til-at-handtere-den-indre-kritiker" aria-label="Permalink to &quot;Strategier til at håndtere den indre kritiker&quot;">​</a></h2><h3 id="_1-navngiv-det-for-at-tæmme-det" tabindex="-1">1. Navngiv det for at tæmme det <a class="header-anchor" href="#_1-navngiv-det-for-at-tæmme-det" aria-label="Permalink to &quot;1. Navngiv det for at tæmme det&quot;">​</a></h3><p>Giv din indre kritiker et navn – noget lidt latterligt. &quot;Åh, der går Negative Nils igen.&quot; Dette skaber afstand mellem dig og stemmen, hvilket gør den lettere at afvise.</p><h3 id="_2-udfordr-beviserne" tabindex="-1">2. Udfordr beviserne <a class="header-anchor" href="#_2-udfordr-beviserne" aria-label="Permalink to &quot;2. Udfordr beviserne&quot;">​</a></h3><p>Når kritikeren siger &quot;du fejler altid under pres&quot;, så spørg dig selv: Er det virkelig sandt? Kan du komme i tanke om tidspunkter, hvor du klarede dig godt under pres? Kritikeren beskæftiger sig med absolutter, der sjældent afspejler virkeligheden.</p><h3 id="_3-omformuler-budskabet" tabindex="-1">3. Omformuler budskabet <a class="header-anchor" href="#_3-omformuler-budskabet" aria-label="Permalink to &quot;3. Omformuler budskabet&quot;">​</a></h3><p>Omdan kritik til coaching:</p><ul><li>&quot;Du kommer til at savne&quot; → &quot;Fokuser på din rutine&quot;</li><li>&quot;Alle ser med&quot; → &quot;Dette er dit øjeblik til at skinne&quot;</li><li>&quot;Du kvæles altid&quot; → &quot;Du har håndteret pres før&quot;</li></ul><h3 id="_4-brug-din-rutine-før-optagelse" tabindex="-1">4. Brug din rutine før optagelse <a class="header-anchor" href="#_4-brug-din-rutine-før-optagelse" aria-label="Permalink to &quot;4. Brug din rutine før optagelse&quot;">​</a></h3><p>En solid <a href="/da/uddannelse/mental-styrke/rutine-før-indtagelse">rutine før indtagelse</a> giver dit sind noget konstruktivt at fokusere på, hvilket giver mindre plads til kritikeren.</p><h3 id="_5-øv-dig-i-selvmedfølelse" tabindex="-1">5. Øv dig i selvmedfølelse <a class="header-anchor" href="#_5-øv-dig-i-selvmedfølelse" aria-label="Permalink to &quot;5. Øv dig i selvmedfølelse&quot;">​</a></h3><p>Behandl dig selv, som du ville behandle en holdkammerat. Ville du sige &quot;du er forfærdelig&quot; til en holdkammerat, der kæmper med det? Selvfølgelig ikke. Vis den samme venlighed til dig selv.</p><h2 id="opbygning-af-en-støttende-indre-stemme" tabindex="-1">Opbygning af en støttende indre stemme <a class="header-anchor" href="#opbygning-af-en-støttende-indre-stemme" aria-label="Permalink to &quot;Opbygning af en støttende indre stemme&quot;">​</a></h2><p>Målet er ikke at bringe den indre kritiker fuldstændig til tavshed – det er næsten umuligt. I stedet skal du udvikle en stærkere, støttende stemme:</p><h3 id="den-støttende-stemme-siger" tabindex="-1">Den støttende stemme siger: <a class="header-anchor" href="#den-støttende-stemme-siger" aria-label="Permalink to &quot;Den støttende stemme siger:&quot;">​</a></h3><ul><li>&quot;Et kast ad gangen&quot;</li><li>&quot;Stol på din træning&quot;</li><li>&quot;Du har gjort det her før&quot;</li><li>&quot;Bliv i nuet&quot;</li><li>&quot;Tag vejret og nulstil&quot;</li></ul><h3 id="daglig-praksis" tabindex="-1">Daglig praksis <a class="header-anchor" href="#daglig-praksis" aria-label="Permalink to &quot;Daglig praksis&quot;">​</a></h3><p>Brug 5 minutter hver dag:</p><ol><li>Husk et øjeblik, hvor du klarede dig godt</li><li>Husk hvordan det føltes i din krop</li><li>Hør hvad din støttende stemme sagde</li><li>Forankre denne følelse med en fysisk gestus (at røre ved din kugle, justere din stilling)</li></ol><h2 id="i-konkurrence" tabindex="-1">I konkurrence <a class="header-anchor" href="#i-konkurrence" aria-label="Permalink to &quot;I konkurrence&quot;">​</a></h2><p>Når den indre kritiker dukker op under en kamp:</p><ol><li><strong>Anerkend det</strong>: &quot;Jeg bemærker, at jeg er selvkritisk&quot;</li><li><strong>Tag en indånding</strong>: Langsom, dyb indånding for at nulstille</li><li><strong>Brug dit anker</strong>: Den fysiske gestus fra din praksis</li><li><strong>Tilbage til rutinen</strong>: Fokuser på din proces før indtagelsen</li></ol><h2 id="den-langsigtede-rejse" tabindex="-1">Den langsigtede rejse <a class="header-anchor" href="#den-langsigtede-rejse" aria-label="Permalink to &quot;Den langsigtede rejse&quot;">​</a></h2><p>At håndtere den indre kritiker er ikke en engangsløsning. Det er en løbende øvelse, der bliver lettere med tiden. Elitespillere eliminerer ikke selvtillid – de lærer at præstere på trods af den.</p><p>Den indre kritiker vil altid være en del af dig. Men med øvelse bliver dens stemme mere stille, og din støttende stemme bliver stærkere. Det er den mentale fordel, der adskiller gode spillere fra store spillere.</p><hr><p>| <em>Relateret: <a href="/da/uddannelse/mental-styrke/håndtering-af-pres">Håndtering af pres</a> | <a href="/da/uddannelse/mental-styrke/rutine-før-indtagelse">Rutine før indtagelse</a> | <a href="/da/uddannelse/mindfulness/teknikker">Mindfulness-teknikker</a></em> |</p>',43)])])}]]);export{n as __pageData,a as default};
